$activeSheets = array_values(array_filter($sheets, static fn (array $sheet): bool => $sheet['excluido_em'] === null));
$billedSheets = count(array_filter($activeSheets, static fn (array $sheet): bool => $sheet['data_faturamento'] !== null));
$query=[];
if (isset($_GET['busca']) && is_string($_GET['busca'])) { $query['busca']=$_GET['busca']; }
if (($_GET['situacao'] ?? '')==='excluidos') { $query['situacao']='excluidos'; }
if (isset($_GET['pagina']) && filter_var($_GET['pagina'],FILTER_VALIDATE_INT)) { $query['pagina']=$_GET['pagina']; }
$back='contrato'.($query ? '?'.http_build_query($query) : '');
$formatDate=static function (?string $value,bool $dateOnly=false): string {
    if (!$value) { return 'Não registrado'; }
    try { return $dateOnly ? (new DateTimeImmutable($value))->format('d/m/Y') :
        (new DateTimeImmutable($value,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone(Config::string('APP_TIMEZONE','America/Cuiaba')))->format('d/m/Y H:i'); }
    catch (Exception) { return 'Data indisponível'; }
};
$draft=$draft ?? null;
$matchesDraft=static function(string $operation,int $resource) use ($draft): bool {
    return is_array($draft) && $draft['operation']===$operation && (int)($draft['item'] ?: $draft['sheet'])===$resource;
};
$draftValue=static function(string $operation,int $resource,string $field,mixed $current='') use ($draft,$matchesDraft): string {
    if ($matchesDraft($operation,$resource) && !$draft['conflict'] && array_key_exists($field,$draft['fields'])) { return $draft['fields'][$field]; }
    return (string)($current ?? '');
};
$draftOpen=static fn(string $operation,int $resource): string => $matchesDraft($operation,$resource) ? ' open' : '';
$draftNotice=static function(string $operation,int $resource,array $current) use ($draft,$matchesDraft): void {
    if (!$matchesDraft($operation,$resource)) { return; }
    if ($draft['message']!=='') { echo '<p class="error-message" role="alert">'.e($draft['message']).'</p>'; }
    $labels=['nome'=>'Nome','marca'=>'Marca','unidade'=>'Unidade','quantidade'=>'Quantidade','preco'=>'Preço unitário R$',
        'observacao'=>'Observação','minimo'=>'Mínimo','maximo'=>'Máximo','abertura'=>'Saldo de abertura',
        'confirmar_abertura'=>'Confirmação da abertura','confirmar'=>'Confirmação da contagem física',
        'tipo'=>'Tipo de movimento','motivo'=>'Justificativa','original'=>'Movimento original','data'=>'Data','faturado'=>'Pedido faturado'];
    if (!$draft['conflict']) {
        echo '<p class="warning-message" role="status">Preenchimento recuperado. A tentativa não foi salva; revise os campos antes de enviar.</p>';
        foreach ($draft['fields'] as $field=>$value) {
            $invalidNumber=in_array($field,['quantidade','minimo','maximo','abertura','original'],true) && $value!=='' && filter_var($value,FILTER_VALIDATE_INT)===false;
            $date=$field==='data' && $value!=='' ? DateTimeImmutable::createFromFormat('!Y-m-d',$value) : null;
            $invalidDate=$field==='data' && $value!=='' && (!$date || $date->format('Y-m-d')!==$value);
            if ($invalidNumber || $invalidDate) { echo '<p>'.e($labels[$field]).' — tentativa não salva: <strong>'.e($value).'</strong></p>'; }
        }
        return;
    }
    echo '<div class="warning-message" role="alert"><p><strong>O registro mudou desde que o formulário foi aberto.</strong> Os campos abaixo usam os dados atuais. Sua tentativa não salva está disponível para conferência; revise e preencha expressamente as alterações desejadas.</p><div class="table-scroll"><table class="table"><thead><tr><th>Campo</th><th>Dados atuais</th><th>Tentativa não salva</th></tr></thead><tbody>';
    foreach ($draft['fields'] as $field=>$value) {
        echo '<tr><th>'.e($labels[$field] ?? $field).'</th><td>'.nl2br(e((string)($current[$field] ?? 'Não registrado'))).'</td><td>'.nl2br(e($value)).'</td></tr>';
    }
    echo '</tbody></table></div></div>';
};
$formContextField='<input type="hidden" name="_form_context" value="'.e($formContext ?? bin2hex(random_bytes(16))).'">';
$unavailableCurrent=is_array($draft) ? ($draft['current'] ?? []) : [];
if (is_array($draft) && $draft['unavailable']) {
    $unavailableCurrent['nome']=$unavailableCurrent['nome_produto'] ?? '';
    $unavailableCurrent['preco']=isset($unavailableCurrent['preco_centavos']) ? number_format((int)$unavailableCurrent['preco_centavos']/100,2,',','') : '';
    $unavailableCurrent['minimo']=$unavailableCurrent['estoque_minimo'] ?? '';
    $unavailableCurrent['maximo']=$unavailableCurrent['estoque_maximo'] ?? '';
    $unavailableCurrent['data']=$unavailableCurrent['data_faturamento'] ?? '';
    if (in_array($draft['operation'],['editar-produto','adicionar-produto'],true)) { $unavailableCurrent['quantidade']=$unavailableCurrent['quantidade_contratada'] ?? ''; }
    elseif (in_array($draft['operation'],['conferir-abertura','movimentar'],true)) { $unavailableCurrent['quantidade']='Saldo registrado atual: '.($unavailableCurrent['saldo'] ?? 'indisponível').' '.($unavailableCurrent['unidade'] ?? ''); }
}
