<?php if ($isAdmin && ($uncertain || $matchesDraft('conferir-abertura',(int)$item['id']))): ?><details id="old-opening-<?= (int)$item['id'] ?>"<?= $draftOpen('conferir-abertura',(int)$item['id']) ?>><summary>Conferir abertura antiga sem comprovação</summary><p>Registre a contagem física feita agora, inclusive zero, na unidade do produto e confira os limites. A operação registra autoria, horário atual e base documental; nenhum histórico é refeito.</p><?php $draftNotice('conferir-abertura',(int)$item['id'],['quantidade'=>$balance,'unidade'=>$item['unidade'],'minimo'=>$item['estoque_minimo'],'maximo'=>$item['estoque_maximo']]); ?><?php if ($uncertain): ?><form method="post" action="<?= e(url('contrato/conferir-abertura/'.$record['id'])) ?>"><input type="hidden" name="_csrf_token" value="<?= e(csrf_token()) ?>"><?= $formContextField ?><input type="hidden" name="produto" value="<?= (int)$item['id'] ?>"><input type="hidden" name="revisao" value="<?= (int)$item['revisao'] ?>"><input type="hidden" name="chave" value="<?= e(bin2hex(random_bytes(16))) ?>"><label>Quantidade física conferida <input name="quantidade" type="number" min="0" required value="<?= e($draftValue('conferir-abertura',(int)$item['id'],'quantidade')) ?>"></label><label>Unidade conferida <input name="unidade" required maxlength="30" value="<?= e($draftValue('conferir-abertura',(int)$item['id'],'unidade',$item['unidade'])) ?>"></label><label>Mínimo <input name="minimo" type="number" min="0" required value="<?= e($draftValue('conferir-abertura',(int)$item['id'],'minimo',$item['estoque_minimo'] ?? '0')) ?>"></label><label>Máximo <input name="maximo" type="number" min="1" required value="<?= e($draftValue('conferir-abertura',(int)$item['id'],'maximo',$item['estoque_maximo'])) ?>"></label><label>Justificativa e documento da conferência <input name="motivo" minlength="10" maxlength="180" required value="<?= e($draftValue('conferir-abertura',(int)$item['id'],'motivo')) ?>"></label><label><input type="checkbox" name="confirmar" value="1" required<?= $draftValue('conferir-abertura',(int)$item['id'],'confirmar')==='1' ? ' checked' : '' ?>> Confirmo que realizei a contagem física atual na quantidade e unidade informadas.</label><button class="btn btn-warning">Registrar conferência atual</button></form><?php else: ?><p><strong>A abertura já foi conferida.</strong> Saldo atual: <?= $balance ?> <?= e($item['unidade']) ?>. A recuperação antiga está encerrada; use o histórico para consultar a conferência registrada.</p><?php endif; ?></details><?php endif; ?>
<?php if (!$pending && !$uncertain): ?><details id="move-stock-<?= (int)$item['id'] ?>"<?= $draftOpen('movimentar',(int)$item['id']) ?>><summary>Registrar entrada ou saída</summary><?php $draftNotice('movimentar',(int)$item['id'],['quantidade'=>'Saldo atual: '.$balance.' '.$item['unidade']]); ?><form method="post" action="<?= e(url('contrato/movimentar/'.$record['id'])) ?>"><input type="hidden" name="_csrf_token" value="<?= e(csrf_token()) ?>"><?= $formContextField ?><input type="hidden" name="produto" value="<?= (int)$item['id'] ?>"><input type="hidden" name="revisao" value="<?= (int)$item['revisao'] ?>"><input type="hidden" name="chave" value="<?= e(bin2hex(random_bytes(16))) ?>"><label>Tipo <select name="tipo"><option value="entrada"<?= $draftValue('movimentar',(int)$item['id'],'tipo','entrada')==='entrada' ? ' selected' : '' ?>>Entrada</option><option value="saida"<?= $draftValue('movimentar',(int)$item['id'],'tipo','entrada')==='saida' ? ' selected' : '' ?>>Saída</option></select></label><label>Quantidade positiva <input name="quantidade" type="number" min="1" required value="<?= e($draftValue('movimentar',(int)$item['id'],'quantidade')) ?>"></label><label>Origem ou destino <input name="motivo" minlength="3" maxlength="300" required value="<?= e($draftValue('movimentar',(int)$item['id'],'motivo')) ?>"></label><button class="btn btn-primary">Registrar</button></form></details><?php endif; ?>
<?php if ($isAdmin && !$pending && !$uncertain): ?><details id="reverse-stock-<?= (int)$item['id'] ?>"<?= $draftOpen('estornar',(int)$item['id']) ?>><summary>Estornar movimento</summary><?php $draftNotice('estornar',(int)$item['id'],[]); ?><form method="post" action="<?= e(url('contrato/movimentar/'.$record['id'])) ?>"><input type="hidden" name="_csrf_token" value="<?= e(csrf_token()) ?>"><?= $formContextField ?><input type="hidden" name="produto" value="<?= (int)$item['id'] ?>"><input type="hidden" name="revisao" value="<?= (int)$item['revisao'] ?>"><input type="hidden" name="tipo" value="estorno"><input type="hidden" name="quantidade" value="1"><input type="hidden" name="chave" value="<?= e(bin2hex(random_bytes(16))) ?>"><label>ID do movimento original <input name="original" type="number" min="1" required value="<?= e($draftValue('estornar',(int)$item['id'],'original')) ?>"></label><label>Justificativa <input name="motivo" minlength="3" maxlength="300" required value="<?= e($draftValue('estornar',(int)$item['id'],'motivo')) ?>"></label><button class="btn btn-warning">Estornar</button></form></details><?php endif; ?>
<details id="delete-product-<?= (int)$item['id'] ?>"><summary>Excluir produto</summary><p>O registro e o histórico serão preservados. Destine todo saldo físico antes de excluir.</p><form method="post" action="<?= e(url('contrato/excluir/'.$record['id'])) ?>"><input type="hidden" name="_csrf_token" value="<?= e(csrf_token()) ?>"><?= $formContextField ?><input type="hidden" name="revisao" value="<?= (int)$record['revisao'] ?>"><input type="hidden" name="produto" value="<?= (int)$item['id'] ?>"><label><input type="checkbox" name="confirmar" value="1" required> Confirmo a exclusão lógica deste produto</label><button class="btn-danger">Excluir produto</button></form></details>
</td></tr><?php endif; ?>
<?php endforeach; ?><?php if (!$hasItems): ?><tr><td colspan="7" class="contract-empty-products">Nenhum produto lançado nesta nota.</td></tr><?php endif; ?></tbody></table></div>
<?php if ($active && $sheet['excluido_em']===null): ?>
<details id="note-observation-<?= (int)$sheet['id'] ?>" class="contract-observation-card" open><summary>Observações da nota <?= (int)$sheet['numero_pagina'] ?></summary><?php $draftNotice('observacao',(int)$sheet['id'],['observacao'=>$sheet['observacao'] ?? '']); ?><form method="post" action="<?= e(url('contrato/editar-folha/'.$record['id'])) ?>"><input type="hidden" name="_csrf_token" value="<?= e(csrf_token()) ?>"><?= $formContextField ?><input type="hidden" name="folha" value="<?= (int)$sheet['id'] ?>"><input type="hidden" name="revisao" value="<?= (int)$sheet['revisao'] ?>"><textarea name="observacao" maxlength="2000" rows="3" class="form-control" aria-label="Observações da nota <?= (int)$sheet['numero_pagina'] ?>" placeholder="Escreva aqui informações adicionais desta nota..."><?= e($draftValue('observacao',(int)$sheet['id'],'observacao',$sheet['observacao'] ?? '')) ?></textarea><div class="contract-inline-actions"><button class="btn-primary">Salvar observações</button></div></form></details>
<details id="delete-note-<?= (int)$sheet['id'] ?>" class="contract-note-delete"><summary>Excluir nota</summary><p>A exclusão é lógica e preserva o histórico. Destine todo saldo físico dos produtos antes de continuar.</p><form method="post" action="<?= e(url('contrato/excluir/'.$record['id'])) ?>"><input type="hidden" name="_csrf_token" value="<?= e(csrf_token()) ?>"><?= $formContextField ?><input type="hidden" name="revisao" value="<?= (int)$record['revisao'] ?>"><input type="hidden" name="folha" value="<?= (int)$sheet['id'] ?>"><label><input type="checkbox" name="confirmar" value="1" required> Confirmo a exclusão lógica desta nota</label><button class="btn-danger">Excluir nota</button></form></details>
<?php else: ?><div class="contract-observation-card"><h4>Observações da nota <?= (int)$sheet['numero_pagina'] ?></h4><p><?= nl2br(e($sheet['observacao'] ?? '')) ?></p></div><?php endif; ?>
</section>
<?php endforeach; ?>
<?php if ($active): ?><div class="contract-secondary-actions"><details id="new-note"<?= $draftOpen('nova-folha',0) ?>><summary>Nova nota com observação</summary><?php $draftNotice('nova-folha',0,[]); ?><form method="post" action="<?= e(url('contrato/folha/'.$record['id'])) ?>"><input type="hidden" name="_csrf_token" value="<?= e(csrf_token()) ?>"><?= $formContextField ?><input type="hidden" name="revisao" value="<?= (int)$record['revisao'] ?>"><input type="hidden" name="copiar" value=""><input type="hidden" name="chave" value=""><label for="observacao">Observação</label><textarea id="observacao" name="observacao" maxlength="2000" class="form-control"><?= e($draftValue('nova-folha',0,'observacao')) ?></textarea><button class="btn-primary">Adicionar nota</button></form></details>
<details id="delete-contract"><summary>Excluir pedido</summary><p>O registro e o histórico continuarão disponíveis. É preciso destinar todo saldo físico antes.</p><form method="post" action="<?= e(url('contrato/excluir/'.$record['id'])) ?>"><input type="hidden" name="_csrf_token" value="<?= e(csrf_token()) ?>"><?= $formContextField ?><input type="hidden" name="revisao" value="<?= (int)$record['revisao'] ?>"><label><input type="checkbox" name="confirmar" value="1" required> Confirmo a exclusão lógica</label><button class="btn-danger">Excluir pedido</button></form></details></div><?php endif; ?>
